//! Authored initial raw source for complete original Loot policy comparisons.
pub const CASES:&[&str]=&["cross_file","excluded_roots","allowed","root_boundaries"];
pub fn files(case:&str)->Option<Vec<(String,Vec<u8>)>>{if !CASES.contains(&case){return None}let definitions="#define CAPABILITIES(T) T/proc/capability_entries()\n#define GLOBAL_PROC_REF(P) #P\n/proc/map_resolver(handler)\n    return\n/proc/resolve()\n    return\n";let roots="CAPABILITIES(/obj/resolved)\n\tmap_resolver(GLOBAL_PROC_REF(resolve))\nCAPABILITIES(/obj/not_root)\n    map_resolver(GLOBAL_PROC_REF(resolve))\n";let body="/obj/resolved/child\n\tvar/list/spawn_types = list(/obj/item)\n\tvar/list/items = list(/obj/item)\n/obj/not_root\n\tvar/list/spawn_types = list(/obj/item)\n/obj/random/proc/spawn_test()\n    return 0\n/obj/reader\n    var/item_to_spawn\n    var/loot_table_type\n    var/text = \"loot_reward(quoted)\"\n";let allowed="/obj/allowed\n    var/item_to_spawn // ALLOW(sys_item_to_spawn/RETAINED): this authored compatibility site intentionally retains the old field\n    // ALLOW(sys_loot_table_datum): the authored declaration proves the exact original rule usage\n    var/loot_table_type\n";let boundaries="/obj/randomized\n\tvar/list/items = list(/obj/item)\n/obj/random/child\n\tvar/list/to_spawn = list(/obj/item)\n/obj/resolved_sibling\n\tvar/list/items = list(/obj/item)\n/obj/resolved/child2\n\tvar/list/possible_items = list(/obj/item)\n";let config=if case=="excluded_roots"{"[lint.\"sys/loot\"]\nexempt_files=['maps/roots.dm']\n"}else{""};let mut rows:Vec<(String,Vec<u8>)>=vec![("code/__defines/loot.dm".into(),definitions.as_bytes().to_vec()),("maps/roots.dm".into(),roots.as_bytes().to_vec()),("code/reader.dm".into(),body.as_bytes().to_vec()),("tools/ci/lint_scopes.toml".into(),config.as_bytes().to_vec())];if case=="allowed"{rows.push(("code/allowed.dm".into(),allowed.as_bytes().to_vec()));}if case=="root_boundaries"{rows.push(("maps/boundaries.dm".into(),boundaries.as_bytes().to_vec()));}let mut paths:Vec<_>=rows.iter().filter(|(name,_)|name.starts_with("code/")&&name.ends_with(".dm")).map(|(name,_)|name.as_str()).collect();paths.sort_by_key(|name|(!name.starts_with("code/__defines/"),*name));let manifest=paths.iter().map(|name|format!("#include \"{name}\"\n")).collect::<String>();rows.push(("deepquarry.dme".into(),manifest.into_bytes()));Some(rows)}
